const SBOX=new Uint8Array(256), RCON=new Uint8Array(11);
(function(){let p=1,q=1;const xt=a=>((a<<1)^((a&0x80)?0x1b:0))&0xff;
 // build sbox via affine transform of multiplicative inverse
 const inv=new Uint8Array(256);
