function expandKey(key){
  const Nk=key.length/4, Nr=Nk+6, W=[];
  for(let i=0;i<Nk;i++) W.push([key[4*i],key[4*i+1],key[4*i+2],key[4*i+3]]);
  for(let i=Nk;i<4*(Nr+1);i++){
    let t=W[i-1].slice();
    if(i%Nk===0){ t.push(t.shift()); t=t.map(b=>SBOX[b]); t[0]^=RCON[i/Nk]; }
    else if(Nk>6 && i%Nk===4){ t=t.map(b=>SBOX[b]); }
    W.push(W[i-Nk].map((b,j)=>b^t[j]));
  }
  return {W,Nr};
}
function encryptBlock(inb,{W,Nr}){
  let s=new Uint8Array(inb);
  const ark=rd=>{for(let c=0;c<4;c++)for(let r=0;r<4;r++)s[4*c+r]^=W[rd*4+c][r];};
  ark(0);
  for(let rd=1;rd<=Nr;rd++){
    for(let i=0;i<16;i++) s[i]=SBOX[s[i]];
    // ShiftRows (column-major: byte 4c+r)
    const t=new Uint8Array(16);
    for(let r=0;r<4;r++) for(let c=0;c<4;c++) t[4*c+r]=s[4*((c+r)%4)+r];
    s=t;
