        s[4*c+1]=a[0]^b[1]^a[2]^b[2]^a[3];
        s[4*c+2]=a[0]^a[1]^b[2]^a[3]^b[3];
        s[4*c+3]=a[0]^b[0]^a[1]^a[2]^b[3];
