export function cbcEncrypt(key,iv,data){
  if(![16,24,32].includes(key.length)) throw new Error('Invalid key size');
  if(iv.length!==16) throw new Error('initialization vector must be 16 bytes');
  const ks=expandKey(key); let prev=new Uint8Array(iv); const out=[];
  for(let i=0;i<data.length;i+=16){
    const blk=data.subarray(i,i+16);
    if(blk.length!==16) throw new Error('plaintext block must be 16 bytes');
    const x=new Uint8Array(16); for(let j=0;j<16;j++) x[j]=blk[j]^prev[j];
    const c=encryptBlock(x,ks); out.push(c); prev=c;
  }
